from boltons.setutils import IndexedSet
import random

def bounds(n):
    vals = {None, 0, 1, -1, n - 1, -n, n, -n - 2, n + 2, n // 2, -(n // 2), -3, 3}
    return sorted((v for v in vals if v is None or -n - 3 <= v <= n + 3),
                  key=lambda v: (v is None, v if v is not None else 0))

def probe(items, removes, label):
    s = IndexedSet(items)
    for r in removes: s.remove(r)
    fresh = IndexedSet([i for i in items if i not in set(removes)])
    lst = list(fresh)
    probs = []
    n = len(s)
    bs = bounds(n)
    for start in bs:
        for stop in bs:
            for step in (None, 1, 2, 3, -1, -2, -3):
                sl = slice(start, stop, step)
                try: got = list(s[sl])
                except Exception as e: got = ('EXC', type(e).__name__)
                try: exp = list(fresh[sl])
                except Exception as e: exp = ('EXC', type(e).__name__)
                if got != exp:
                    probs.append(('sl', (start, stop, step), got[:6], exp[:6]))
    step1 = [i for i in bs if i is None or i >= 0]
    for start in step1:
        for stop in step1:
            sl = slice(start, stop, None)
            ref = list(s)
            got, exp = list(s[sl]), ref[sl]
            if got != exp:
                probs.append(('list-slice', (start, stop), got[:6], exp[:6]))
    idxs = [i for i in range(-n - 3, n + 3)]
    for i in idxs:
        try: got = s[i]
        except IndexError: got = 'IDXERR'
        try: exp = lst[i]
        except IndexError: exp = 'IDXERR'
        if got != exp: probs.append(('idx', i, got, exp))
    print(label, 'len', n, 'dead', s._dead_index_count, 'problems', len(probs))
    for p in probs[:8]: print('   ', p)

