from itertools import combinations, product
from boltons.setutils import IndexedSet

fails = []
N = 6
base = list(range(N))
all_removes = [c for r in range(N + 1) for c in combinations(base, r)]

for removes in all_removes:
    s = IndexedSet(base)
    for r in removes: s.remove(r)
    fresh = IndexedSet([i for i in base if i not in set(removes)])
    ref = list(s)
    n = len(s)
    # slices: all bounds -8..8, steps -4..4 (0 raises for both)
    for start, stop, step in product(range(-N - 2, N + 3), repeat=3):
        if step == 0:
            continue
        sl = slice(start, stop, step)
        try: got = list(s[sl])
        except Exception as e: got = ('EXC', type(e).__name__)
        try: exp = list(fresh[sl])
        except Exception as e: exp = ('EXC', type(e).__name__)
        if got != exp:
            fails.append(('vs-fresh', removes, (start, stop, step), got, exp))
        if step > 0:
            exp2 = ref[sl]
            if got != exp2:
                fails.append(('vs-list', removes, (start, stop, step), got, exp2))
    # integer indexing: all positions -8..8
    for i in range(-N - 2, N + 2):
        try: got = s[i]
        except IndexError: got = 'IDXERR'
        try: exp = ref[i]
        except IndexError: exp = 'IDXERR'
        if got != exp:
            fails.append(('idx', removes, i, got, exp))
    # pop: all positions -8..8, against list semantics
    for i in range(-N - 2, N + 2):
        s2 = IndexedSet(base)
        for r in removes: s2.remove(r)
        r2 = list(s2)
        try: got = s2.pop(i); gres = (got, list(s2))
        except IndexError: gres = 'IDXERR'
        except Exception as e: gres = ('EXC', type(e).__name__)
        try:
            e = r2.pop(i); eres = (e, r2)
        except IndexError: eres = 'IDXERR'
        except Exception as e: eres = ('EXC', type(e).__name__)
        if gres != eres:
            fails.append(('pop', removes, i, gres, eres))

print('total fails:', len(fails))
for f in fails[:20]: print(f)
