    "binary": ("KiB","MiB","GiB","TiB","PiB","EiB","ZiB","YiB","RiB","QiB"),
    "gnu": "KMGTPEZYRQ",
}

def check(v, mode_kw, fmt="%.1f"):
    out = humanize.naturalsize(v, format=fmt, **mode_kw)
    gnu = mode_kw.get("gnu", False)
    base = 1024 if (gnu or mode_kw.get("binary")) else 1000
    suffix = suffixes["gnu" if gnu else ("binary" if mode_kw.get("binary") else "decimal")]
    # parse output: number + optional space + unit
