    m = re.match(r"^(-?[\d.]+(?:e[+-]?\d+)?)\s*(.*)$", out)
    if not m:
        return f"UNPARSEABLE: {out!r}"
    shown = float(m.group(1))
    unit = m.group(2)
    if unit not in suffix:
