    if abs(shown) >= base:
        return f"BOUNCED? v={v} fmt={fmt} -> {out!r} (shown={shown} >= {base} at unit index {e})"
    if e != exp0 and abs(shown) < base and abs(abs(shown) - base) > 0.05*base:
        return f"SUSPECT unit move: v={v} -> {out!r} exp0={exp0} e={e}"
    return None

