def sig_digits(s):
    # strip sign, unit/prefix/space; count significant digits of the number part
    m = re.match(r'^(-?)(\d+)(?:\.(\d+))?([a-zA-ZμΩ°].*)?$', s)
    if not m:
        return None  # scientific or other
    intpart, frac, rest = m.group(2), m.group(3) or '', m.group(4) or ''
    # significant digits: int part (no leading zeros here) + frac, but trailing
    # zeros in int part are significant due to rounding; frac always significant
    # after decimal point present. If no frac, all int digits significant.
    return len(intpart.lstrip('0') or '0') + (len(frac) if frac else 0) if intpart != '0' else len(frac.lstrip('0'))

