      try { up = upSubset(a, b, options) } catch (e) { up = 'ERR:' + e.message }

      const key = JSON.stringify([a, b, options])
      if (got !== truth) {
        mismatches.push({ key, truth, got, up, kind: 'patched-vs-truth' })
      }
      if (up !== truth) {
        mismatches.push({ key, truth, got, up, kind: 'upstream-vs-truth' })
      }
    }
  }
}
// dedupe report
const patched = mismatches.filter(x => x.kind === 'patched-vs-truth')
const upstream = mismatches.filter(x => x.kind === 'upstream-vs-truth')
console.log('patched mismatches:', patched.length)
for (const x of patched.slice(0, 40)) console.log('  ', x.key, 'truth=', x.truth, 'got=', x.got, 'upstream=', x.up)
console.log('upstream mismatches:', upstream.length)
for (const x of upstream.slice(0, 40)) console.log('  ', x.key, 'truth=', x.truth, 'got=', x.got)
